mkitem!{mkimpl!{# [stable (feature = "vecdeque_vec_conversions" , since = "1.10.0")] impl < T , A : Allocator > From < VecDeque < T , A > > for Vec < T , A > { # [doc = " Turn a [`VecDeque<T>`] into a [`Vec<T>`]."] # [doc = ""] # [doc = " [`Vec<T>`]: crate::vec::Vec"] # [doc = " [`VecDeque<T>`]: crate::collections::VecDeque"] # [doc = ""] # [doc = " This never needs to re-allocate, but does need to do *O*(*n*) data movement if"] # [doc = " the circular buffer doesn't happen to be at the beginning of the allocation."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::collections::VecDeque;"] # [doc = ""] # [doc = " // This one is *O*(1)."] # [doc = " let deque: VecDeque<_> = (1..5).collect();"] # [doc = " let ptr = deque.as_slices().0.as_ptr();"] # [doc = " let vec = Vec::from(deque);"] # [doc = " assert_eq!(vec, [1, 2, 3, 4]);"] # [doc = " assert_eq!(vec.as_ptr(), ptr);"] # [doc = ""] # [doc = " // This one needs data rearranging."] # [doc = " let mut deque: VecDeque<_> = (1..5).collect();"] # [doc = " deque.push_front(9);"] # [doc = " deque.push_front(8);"] # [doc = " let ptr = deque.as_slices().1.as_ptr();"] # [doc = " let vec = Vec::from(deque);"] # [doc = " assert_eq!(vec, [8, 9, 1, 2, 3, 4]);"] # [doc = " assert_eq!(vec.as_ptr(), ptr);"] # [doc = " ```"] fn from (mut other : VecDeque < T , A >) -> Self { other . make_contiguous () ; unsafe { let other = ManuallyDrop :: new (other) ; let buf = other . buf . ptr () ; let len = other . len () ; let cap = other . capacity () ; let alloc = ptr :: read (other . allocator ()) ; if other . head != 0 { ptr :: copy (buf . add (other . head) , buf , len) ; } Vec :: from_raw_parts_in (buf , len , cap , alloc) } } }}}
mkitem!{mkimpl!{# [stable (feature = "std_collections_from_array" , since = "1.56.0")] impl < T , const N : usize > From < [T ; N] > for VecDeque < T > { # [doc = " Converts a `[T; N]` into a `VecDeque<T>`."] # [doc = ""] # [doc = " ```"] # [doc = " use std::collections::VecDeque;"] # [doc = ""] # [doc = " let deq1 = VecDeque::from([1, 2, 3, 4]);"] # [doc = " let deq2: VecDeque<_> = [1, 2, 3, 4].into();"] # [doc = " assert_eq!(deq1, deq2);"] # [doc = " ```"] # [track_caller] fn from (arr : [T ; N]) -> Self { let mut deq = VecDeque :: with_capacity (N) ; let arr = ManuallyDrop :: new (arr) ; if ! < T > :: IS_ZST { unsafe { ptr :: copy_nonoverlapping (arr . as_ptr () , deq . ptr () , N) ; } } deq . head = 0 ; deq . len = N ; deq } }}}